create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role text not null default 'customer' check (role in ('customer','service_provider','admin')), created_at timestamptz not null default now()); create table public.provider_status (provider_id uuid primary key references public.profiles(id) on delete cascade, available_for_work boolean not null default true, wallet_balance numeric(12,2) not null default 100, current_booking_id uuid, next_booking_id uuid, updated_at timestamptz not null default now()); create table public.provider_skills (provider_id uuid references public.profiles(id) on delete cascade, skill text not null, approved boolean not null default false, primary key(provider_id,skill)); create table public.bookings (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.profiles(id), provider_id uuid references public.profiles(id), next_provider_id uuid references public.profiles(id), category text not null, service_name text not null, quantity integer not null default 1 check(quantity>0), unit_price numeric(12,2), booking_amount numeric(12,2), payment_method text check(payment_method in ('online','cash')), address text, latitude double precision, longitude double precision, status text not null default 'searching', start_otp text, work_not_completed_reason text, visit_charge numeric(12,2), customer_completion_confirmed boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); alter table public.provider_status add constraint provider_status_current_fk foreign key(current_booking_id) references public.bookings(id) on delete set null; alter table public.provider_status add constraint provider_status_next_fk foreign key(next_booking_id) references public.bookings(id) on delete set null; create table public.booking_quotes (id uuid primary key default gen_random_uuid(), booking_id uuid not null references public.bookings(id) on delete cascade, provider_id uuid not null references public.profiles(id), amount numeric(12,2) not null check(amount>=0), status text not null default 'pending' check(status in ('pending','accepted','rejected','revised','cancelled')), created_at timestamptz not null default now()); create table public.booking_status_events (id bigint generated by default as identity primary key, booking_id uuid not null references public.bookings(id) on delete cascade, actor_id uuid references public.profiles(id), status text not null, note text, created_at timestamptz not null default now()); create table public.wallet_transactions (id bigint generated by default as identity primary key, provider_id uuid not null references public.profiles(id), booking_id uuid references public.bookings(id), amount numeric(12,2) not null, kind text not null check(kind in ('welcome_bonus','recharge','platform_charge','adjustment')), created_at timestamptz not null default now()); alter table public.profiles enable row level security; alter table public.provider_status enable row level security; alter table public.provider_skills enable row level security; alter table public.bookings enable row level security; alter table public.booking_quotes enable row level security; alter table public.booking_status_events enable row level security; alter table public.wallet_transactions enable row level security; create policy profiles_self_select on public.profiles for select to authenticated using (id=auth.uid()); create policy profiles_self_update on public.profiles for update to authenticated using (id=auth.uid()) with check(id=auth.uid()); create policy provider_status_read on public.provider_status for select to authenticated using (provider_id=auth.uid()); create policy provider_status_update on public.provider_status for update to authenticated using(provider_id=auth.uid()) with check(provider_id=auth.uid()); create policy provider_skills_read on public.provider_skills for select to authenticated using(provider_id=auth.uid()); create policy bookings_participant_read on public.bookings for select to authenticated using(customer_id=auth.uid() or provider_id=auth.uid() or next_provider_id=auth.uid()); create policy bookings_customer_insert on public.bookings for insert to authenticated with check(customer_id=auth.uid()); create policy bookings_customer_update on public.bookings for update to authenticated using(customer_id=auth.uid()) with check(customer_id=auth.uid()); create policy quotes_participant_read on public.booking_quotes for select to authenticated using(provider_id=auth.uid() or exists(select 1 from public.bookings b where b.id=booking_id and b.customer_id=auth.uid())); create policy quotes_provider_insert on public.booking_quotes for insert to authenticated with check(provider_id=auth.uid()); create policy events_participant_read on public.booking_status_events for select to authenticated using(exists(select 1 from public.bookings b where b.id=booking_id and (b.customer_id=auth.uid() or b.provider_id=auth.uid() or b.next_provider_id=auth.uid()))); create policy wallet_self_read on public.wallet_transactions for select to authenticated using(provider_id=auth.uid()); create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,phone,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.phone,coalesce(new.raw_user_meta_data->>'role','customer')); if coalesce(new.raw_user_meta_data->>'role','customer')='service_provider' then insert into public.provider_status(provider_id,wallet_balance) values(new.id,100); insert into public.wallet_transactions(provider_id,amount,kind) values(new.id,100,'welcome_bonus'); end if; return new; end; $$; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user(); create or replace function public.accept_booking(p_booking_id uuid) returns public.bookings language plpgsql security definer set search_path=public as $$ declare b public.bookings; ps public.provider_status; begin select * into ps from public.provider_status where provider_id=auth.uid() for update; if ps.provider_id is null or not ps.available_for_work then raise exception 'Provider unavailable'; end if; select * into b from public.bookings where id=p_booking_id for update; if b.id is null or b.status <> 'searching' or b.provider_id is not null then raise exception 'Booking no longer available'; end if; if ps.current_booking_id is null then update public.bookings set provider_id=auth.uid(),status='accepted',updated_at=now() where id=p_booking_id returning * into b; update public.provider_status set current_booking_id=p_booking_id,updated_at=now() where provider_id=auth.uid(); elsif ps.next_booking_id is null then update public.bookings set next_provider_id=auth.uid(),status='next_accepted',updated_at=now() where id=p_booking_id returning * into b; update public.provider_status set next_booking_id=p_booking_id,updated_at=now() where provider_id=auth.uid(); else raise exception 'Provider already has Current + Next job'; end if; insert into public.booking_status_events(booking_id,actor_id,status) values(p_booking_id,auth.uid(),b.status); return b; end; $$; revoke all on function public.accept_booking(uuid) from public; grant execute on function public.accept_booking(uuid) to authenticated; alter publication supabase_realtime add table public.bookings; alter publication supabase_realtime add table public.booking_quotes; alter publication supabase_realtime add table public.booking_status_events;
